<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php'; require_login();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM equipment WHERE id=?');$s->execute([$id]);$item=$s->fetch(PDO::FETCH_ASSOC);if(!$item)exit('Equipment not found.');$h=$pdo->prepare('SELECT mr.*,u.name technician,w.work_order_code FROM maintenance_records mr LEFT JOIN users u ON u.id=mr.technician_id LEFT JOIN work_orders w ON w.id=mr.work_order_id WHERE mr.equipment_id=? ORDER BY maintenance_date DESC');$h->execute([$id]);$history=$h->fetchAll(PDO::FETCH_ASSOC);$page_title=$item['equipment_name'];require __DIR__.'/../includes/header.php';?><style>
.maintenance-history-table>thead th{background:#18212b;color:#fff;padding:14px 10px;border-bottom:3px solid #ff9a1b;font-weight:700}
.maintenance-history-table>thead th:nth-last-child(2){background:#ff9a1b;color:#18212b}
.maintenance-history-table>tbody td{padding:14px 10px;border-bottom:1px solid #e4e9ee}
.maintenance-history-table>tbody tr:nth-child(even)>td{background-color:#f5f8fb}
.maintenance-history-table>tbody td.maintenance-total{background:#fff2dc;color:#945400;font-weight:750;white-space:nowrap}
</style>
<div class="d-flex justify-content-between mb-4"><div><h1 class="page-heading"><?=e($item['equipment_name'])?></h1><p class="page-subtitle mb-0"><?=e($item['category'])?></p></div><?php if(is_system_admin()):?><a class="btn btn-primary" href="edit.php?id=<?=$id?>"><?=e(t('edit_equipment'))?></a><?php endif?></div><div class="row g-4"><div class="col-lg-4"><div class="panel"><span class="badge status-<?=str_replace(' ','-',$item['status'])?> mb-3"><?=e(tv($item['status']))?></span><dl class="row small"><dt class="col-5"><?=e(t('location'))?></dt><dd class="col-7"><?=e($item['location'])?></dd><dt class="col-5"><?=e(t('serial_number'))?></dt><dd class="col-7"><?=e($item['serial_number'])?></dd><dt class="col-5"><?=e(t('condition'))?></dt><dd class="col-7"><?=e(tv($item['condition_status']))?></dd><dt class="col-5"><?=e(t('purchase_date'))?></dt><dd class="col-7"><?=e($item['purchase_date']??'Not recorded')?></dd><dt class="col-5"><?=e(t('warranty'))?></dt><dd class="col-7"><?=e($item['warranty_expiry'])?></dd></dl><p><?=nl2br(e($item['description']))?></p></div></div><div class="col-lg-8"><div class="panel"><h2 class="h6 mb-3"><?=e(t('history'))?></h2><p>Completed repairs: <b><?=count(array_filter($history,fn($record)=>$record['status']==='Completed'))?></b> · Total history records: <?=count($history)?></p><div class="table-responsive"><table class="table table-hover maintenance-history-table"><thead><tr><th><?=e(t('date'))?></th><th>Work Order</th><th><?=e(t('problem'))?></th><th><?=e(t('action'))?></th><th><?=e(t('technician'))?></th><th>Labour Cost</th><th>Parts Cost</th><th>Other Cost</th><th>Total Cost</th><th><?=e(t('status'))?></th></tr></thead><tbody><?php foreach($history as $x):?><tr><td><?=e($x['maintenance_date'])?></td><td><?=e($x['work_order_code']??'Not linked')?></td><td><?=e($x['problem_description'])?></td><td><?=e($x['action_taken'])?></td><td><?=e($x['technician']??'—')?></td><?php foreach(['labour_cost','parts_cost','other_cost','total_cost'] as $costField):?><td class="<?= $costField === 'total_cost' ? 'maintenance-total' : '' ?>">RM <?=number_format((float)$x[$costField],2)?></td><?php endforeach?><td><span class="badge status-<?=e($x['status'])?>"><?=e(tv($x['status']))?></span></td></tr><?php endforeach; if(!$history):?><tr><td colspan="10" class="text-center text-muted py-4">No maintenance history yet.</td></tr><?php endif?></tbody></table></div></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
